const VIRTUAL_W = 640;
const VIRTUAL_H = 480;

// Set from onRuntimeInitialized. Guards calls into the wasm module - see scheduleDisplayResize.
let runtimeReady = false;

// Single source of truth for canvas geometry, also read from C++ (see
// crt_filter_update_web_display_size). cssW/cssH is the largest 4:3 box that fits on the page.
// It is authoritative and is never derived from the backbuffer: allegro sizes the backbuffer by
// scaling the CSS size, so deriving one from the other in both directions makes the two chase
// each other. bufW/bufH is that same box measured in physical pixels. A display shader must
// render into exactly bufW x bufH, because any other backbuffer size makes the browser resample
// the shaded image, which turns its scanlines and mask into moire.
function canvasSize() {
  // <main> is what goes fullscreen, so the header is off screen then - but it is still laid out
  // and still reports its height, and subtracting it would waste a band of the screen.
  const headerH = document.fullscreenElement ? 0 : document.querySelector('header').clientHeight;
  const heightAvail = innerHeight - headerH;
  const scale = Math.min(innerWidth / VIRTUAL_W, heightAvail / VIRTUAL_H);
  const cssW = Math.max(0, Math.floor(VIRTUAL_W * scale));
  const cssH = Math.max(0, Math.floor(VIRTUAL_H * scale));
  return {
    cssW, cssH,
    // Never smaller than the virtual screen: the display is created at bufW x bufH, and a page
    // that is hidden or still laying out reports a zero-sized viewport.
    bufW: Math.max(VIRTUAL_W, Math.round(cssW * devicePixelRatio)),
    bufH: Math.max(VIRTUAL_H, Math.round(cssH * devicePixelRatio)),
  };
}
window.zcCanvasSize = canvasSize;

function applyCanvasCss() {
  const {cssW, cssH} = canvasSize();
  canvas.style.width = cssW + "px";
  canvas.style.height = cssH + "px";
  // A backbuffer larger than the virtual screen means a display shader already shaded this at
  // device resolution - nearest-neighbor would re-alias what it just drew.
  canvas.style.imageRendering = canvas.width > VIRTUAL_W ? 'auto' : '';
}

function resize() {
  applyCanvasCss();
  // The backbuffer was sized for the viewport as it was when the display was created, so on its
  // own this would leave the game in a box the size of the old viewport - very visible when
  // going fullscreen.
  scheduleDisplayResize();
}

let displayResizeTimer;
// Resizing the display wipes render target contents, so coalesce the burst of resize events a
// window drag produces rather than doing it for every one. C++ works out the size it wants and
// returns without touching anything if the canvas already matches.
function scheduleDisplayResize() {
  clearTimeout(displayResizeTimer);
  displayResizeTimer = setTimeout(() => {
    // Merely *reading* an export before the wasm module is initialized aborts the runtime, so
    // this has to be a real check and not optional chaining on the property. Nothing is lost by
    // skipping: the display does not exist yet either, and it is created at whatever
    // zcCanvasSize() reports at the time.
    if (!runtimeReady) return;
    // Reading the property is safe once initialized; the ?.() only guards against a stale wasm
    // built before the export existed.
    window.Module._zc_web_display_size_changed?.();
  }, 100);
}

// Sites a quest's project page may be on. Others are labeled by hostname.
const projectSiteNames = {
  'www.purezc.net': 'PureZC',
  'www.zcland.net': 'ZC Land',
};

// 0 for quests with no rating, or a rating without any votes.
function getRatingVotes(quest) {
  return quest.rating?.distribution?.reduce((a, b) => a + b, 0) ?? 0;
}

async function renderQuestList() {
  const questListEl = document.querySelector('.quest-list');
  const questListEntriesEl = questListEl.querySelector('.quest-list__entries-list');
  const questListCurrentEl = questListEl.querySelector('.quest-list__current');
  const questListCurrentTemplate = document.querySelector('.tmpl-selected-quest');

  const manifest = await ZC.getQuestManifest();
  const quests = Object.values(manifest);

  for (const quest of quests) {
    if (quest.type !== 'quests') continue;
    if (!['auto', true].includes(quest.approval)) continue;

    const el = document.createElement('div');
    el.classList.add('quest-list__entry');
    el.setAttribute('data-quest-index', quests.indexOf(quest));
    el.quest = quest;
    el.append(quest.name);
    questListEntriesEl.append(el);
    el.tabIndex = -1;
  }

  questListEntriesEl.addEventListener('keyup', (e) => {
    if (e.keyCode === 38 && e.target.previousElementSibling) {
      const questIndex = Number(e.target.previousElementSibling.getAttribute('data-quest-index'));
      const quest = quests[questIndex];
      showQuest(quest);
      e.target.previousElementSibling.focus();
    } else if (e.keyCode === 40 && e.target.nextElementSibling) {
      const questIndex = Number(e.target.nextElementSibling.getAttribute('data-quest-index'));
      const quest = quests[questIndex];
      showQuest(quest);
      e.target.nextElementSibling.focus();
    }
  });

  function showQuest(quest) {
    const questPrefix = `${ZC.dataOrigin}/${quest.id}`;

    document.querySelector('.quest-list__entry.selected')?.classList.remove('selected');
    // Not in the list if linked to with ?quest= but not approved.
    document.querySelector(`.quest-list__entry[data-quest-index="${quests.indexOf(quest)}"]`)?.classList.add('selected');

    const contentEl = questListCurrentTemplate.content.cloneNode(true).children[0];

    function fillOrDelete(selector, value) {
      if (value) {
        contentEl.querySelector(selector).textContent = value;
      } else {
        contentEl.querySelector(selector).parentElement.remove();
      }
    }

    fillOrDelete('.name', quest.name);
    fillOrDelete('.author', quest.authors.map(a => a.name).join(', '));
    fillOrDelete('.genre', quest.genre);
    fillOrDelete('.version', quest.zcVersion);

    const projectLinkEl = contentEl.querySelector('.project-link');
    if (quest.projectUrl) {
      const host = new URL(quest.projectUrl).hostname;
      projectLinkEl.href = quest.projectUrl;
      projectLinkEl.textContent = `View on ${projectSiteNames[host] ?? host}`;
    } else {
      projectLinkEl.remove();
    }

    const ratingVotes = getRatingVotes(quest);
    if (ratingVotes) {
      contentEl.querySelector('.rating').textContent = quest.rating.score;
      contentEl.querySelector('.rating-votes').textContent = ratingVotes;
    } else {
      contentEl.querySelector('._rating').remove();
    }

    if (quest.informationHtml) contentEl.querySelector('.information').append(sanitizeHtml(quest.informationHtml));
    if (quest.descriptionHtml) contentEl.querySelector('.description').append(sanitizeHtml(quest.descriptionHtml));
    if (quest.storyHtml) contentEl.querySelector('.story').append(sanitizeHtml(quest.storyHtml));
    if (quest.tipsAndCheatsHtml) contentEl.querySelector('.tips').append(sanitizeHtml(quest.tipsAndCheatsHtml));
    if (quest.creditsHtml) contentEl.querySelector('.credits').append(sanitizeHtml(quest.creditsHtml));

    function setCurImage(image) {
      const imgEl = document.createElement('img');
      imgEl.crossOrigin = 'anonymous';
      imgEl.src = `${questPrefix}/${image}`;
      contentEl.querySelector('.current-image').innerHTML = '';
      contentEl.querySelector('.current-image').append(imgEl);
    }

    const imagesEl = contentEl.querySelector('.images');
    if (quest.images.length > 1) {
      for (const image of quest.images) {
        const imgEl = document.createElement('img');
        imgEl.crossOrigin = 'anonymous';
        imgEl.src = `${questPrefix}/${image}`;
        imagesEl.append(imgEl);
        imgEl.addEventListener('click', () => {
          setCurImage(image);
        });
        imgEl.addEventListener('mouseover', () => {
          setCurImage(image);
        });
      }
    }

    if (quest.images.length > 0) setCurImage(quest.images[0]);

    const release = quest.releases[0];
    const qsts = release.resources.filter(r => r.toLowerCase().endsWith('.qst'));
    for (const resource of qsts) {
      // Only set `name` query param, which doesn't do anything, when making a link for
      // a quest that only has a single qst file. Otherwise, to disambiguate use the entire
      // file path (which likely makes obvious the name of the quest).
      const openParamValue = qsts.length > 1 ?
        `${quest.id}/${release.name}/${resource}` :
        quest.id;
      const args = {open: openParamValue};
      if (qsts.length === 1) {
        args.name = quest.name.replace(/['!?]/g, '').replace(/[\s:&]+/g, '-').replace(/[-]+/g, '-');
      }

      const playEl = createElement('a', 'play-link');
      playEl.href = createUrlString(ZC_Constants.zeldaUrl, args);
      playEl.textContent = 'Play!';

      const editEl = createElement('a');
      editEl.href = createUrlString(ZC_Constants.zquestUrl, args);
      editEl.textContent = 'Open in Editor';

      const el = createElement('div', 'link-group');
      contentEl.querySelector('.links').append(el);
      el.append(resource, playEl, editEl);
    }

    questListCurrentEl.textContent = '';
    questListCurrentEl.append(contentEl);
  }

  questListEntriesEl.addEventListener('click', (e) => {
    const entryEl = e.target.closest('.quest-list__entry');
    if (!entryEl) return;

    const questIndex = Number(entryEl.getAttribute('data-quest-index'));
    const quest = quests[questIndex];
    showQuest(quest);
  });

  function sortEntries(field) {
    for (const el of document.querySelectorAll('.quest-list__sort-option')) {
      el.classList.toggle('selected', el.textContent === field);
    }

    const byName = (a, b) => a.textContent.localeCompare(b.textContent);

    let sortBy = byName;
    if (field === 'Rating') {
      // Unrated quests go last.
      const score = (quest) => getRatingVotes(quest) ? quest.rating.score : -Infinity;
      sortBy = (a, b) => (score(b.quest) - score(a.quest)) || byName(a, b);
    }

    [...questListEntriesEl.children]
      .sort(sortBy)
      .forEach(node => questListEntriesEl.appendChild(node));
  }

  for (const el of document.querySelectorAll('.quest-list__sort-option')) {
    el.addEventListener('click', () => sortEntries(el.textContent));
  }
  sortEntries('Rating');

  const qsQuest = new URLSearchParams(location.search).get('quest');
  const qsQuestId = qsQuest ? qsQuest.match(/quests\/[^/]+\/[^/?#]+/)?.[0] : '';
  const initialSelectedQuest = (qsQuestId && quests.find(q => q.id == qsQuestId)) || questListEntriesEl.firstElementChild?.quest;
  if (initialSelectedQuest) showQuest(initialSelectedQuest);
}

// The optional browser features the app uses, for the About panel.
function getBrowserFeatures() {
  return [
    {
      name: 'Threads (SharedArrayBuffer) - required',
      supported: typeof SharedArrayBuffer === 'function' && self.crossOriginIsolated,
    },
    {
      name: 'Attach a folder from your computer (File System Access)',
      supported: !!self.showDirectoryPicker,
    },
    {
      name: 'Default controls shown for your keyboard layout',
      supported: !!navigator.keyboard?.getLayoutMap,
    },
    {
      name: 'Gamepads',
      supported: !!navigator.getGamepads,
    },
    {
      name: 'Fullscreen',
      supported: !!document.fullscreenEnabled,
    },
    {
      name: 'Persistent storage (the browser won\'t clear your saves to free space)',
      supported: !!navigator.storage?.persist,
    },
    {
      name: 'Works offline (service worker)',
      supported: 'serviceWorker' in navigator,
    },
  ];
}

function renderBrowserSupport() {
  const features = getBrowserFeatures();
  const el = document.querySelector('.browser-support');
  el.textContent = '';
  el.append(createElement('h3', '', 'Browser support'));
  const fullySupported = features.every(f => f.supported);
  el.append(createElement('p', '', fullySupported ? 'This browser is fully supported.' : 'This browser is partially supported.'));

  const listEl = createElement('ul');
  for (const { name, supported } of features) {
    listEl.append(createElement('li', supported ? '' : 'unsupported', `${supported ? '✅' : '❌'} ${name}`));
  }
  el.append(listEl);
}

async function renderDefaultControls() {
  const layout = await navigator.keyboard.getLayoutMap();
  const defaultControls = {
    A: 'KeyZ', // Physical location: Bottom row, left key (US 'Z', German 'Y')
    B: 'KeyX',
    L: 'KeyQ',
    R: 'KeyW',
    Start: 'Enter',
    Map: 'Space',
    'Ex1 (X)': 'KeyA',
    'Ex1 (Y)': 'KeyS',
    Ex3: 'KeyD',
    Ex4: 'KeyC',
  };

  const defaultControlsEl = document.querySelector('.default-controls');
  defaultControlsEl.textContent = 'Default Keyboard Controls';

  for (const [name, code] of Object.entries(defaultControls)) {
    const el = createElement('div');
    defaultControlsEl.append(el);
    const label = await layout.get(code) ?? code.replace('Key', '');
    el.textContent = `${name}: ${label}`;
  }
}

function setupTouchControls() {
  const BUTTON_MAP = {
    'A':     { code: 'KeyZ', key: 'z', keyCode: 90 },
    'B':     { code: 'KeyX', key: 'x', keyCode: 88 },
    'Start': { code: 'Enter', key: 'Enter', keyCode: 13 },
    'Map':   { code: 'Space', key: ' ', keyCode: 32 },
    'L':     { code: 'KeyA', key: 'a', keyCode: 65 },
    'R':     { code: 'KeyS', key: 's', keyCode: 83 },
    'Left':  { code: 'ArrowLeft', key: 'ArrowLeft', keyCode: 37 },
    'Right': { code: 'ArrowRight', key: 'ArrowRight', keyCode: 39 },
    'Up':    { code: 'ArrowUp', key: 'ArrowUp', keyCode: 38 },
    'Down':  { code: 'ArrowDown', key: 'ArrowDown', keyCode: 40 },
  };

  const getDirectionalAction = (x, y) => {
    if (x === -1) return 'Left';
    if (x === 1) return 'Right';
    if (y === 1) return 'Down';
    if (y === -1) return 'Up';
    return null;
  };

  const sendDOMKeyEvent = (touchType, action) => {
    const keyDef = BUTTON_MAP[action];
    if (!keyDef) return;

    // Convert the touch state into a standard key down/up event.
    let eventType;
    if (touchType === 'touchstart' || touchType === 'touchmove') eventType = 'keydown';
    if (touchType === 'touchend') eventType = 'keyup';

    const event = new KeyboardEvent(eventType, {
      bubbles: true,
      cancelable: true,
      code: keyDef.code,
      key: keyDef.key,
      keyCode: keyDef.keyCode,
      which: keyDef.keyCode
    });

    // Dispatch to the document so Emscripten/SDL catches it naturally.
    document.dispatchEvent(event);
  };

  const getActionsForInputElement = (el) => {
    const action = el.getAttribute('data-action');
    if (action) return [action];

    const actions = [];
    const x = Number(el.getAttribute('data-x'));
    const y = Number(el.getAttribute('data-y'));
    if (x) actions.push(getDirectionalAction(x, 0));
    if (y) actions.push(getDirectionalAction(0, y));

    return actions;
  }

  for (const touchInputsEl of document.querySelectorAll('.touch-inputs')) {
    let activeInputEl = null;
    const setActiveInputEl = el => {
      if (activeInputEl) activeInputEl.classList.remove('pressed');
      activeInputEl = el;
      if (activeInputEl) activeInputEl.classList.add('pressed');
    };

    const touchFn = (eventType, e) => {
      let touch;
      if (eventType === 'touchend') {
        if (e.targetTouches.length !== 0) return;
        touch = e.changedTouches[0];
      } else {
        if (e.targetTouches.length !== 1) return;
        touch = e.targetTouches[0];
      }

      const elementMouseIsOver = document.elementFromPoint(touch.clientX, touch.clientY);
      const inputEl = elementMouseIsOver && elementMouseIsOver.classList.contains('touch-input') ? elementMouseIsOver : null;

      // In the "dead zone" between the inputs (ex: the middle of the dpad).
      if (!inputEl && elementMouseIsOver && elementMouseIsOver.closest('.touch-inputs') === touchInputsEl && eventType !== 'touchend') {
        return;
      }

      // Release the old key if we slid off it.
      if (activeInputEl && (inputEl !== activeInputEl || !inputEl)) {
        for (const action of getActionsForInputElement(activeInputEl)) {
          sendDOMKeyEvent('touchend', action);
        }
      }

      if (!inputEl) {
        setActiveInputEl(null);
        return;
      }

      // Press the new key.
      for (const action of getActionsForInputElement(inputEl)) {
        sendDOMKeyEvent(eventType, action);
      }

      setActiveInputEl(eventType === 'touchend' ? null : inputEl);
    };

    touchInputsEl.addEventListener('touchstart', e => {
      e.preventDefault(); // Kills the long-press haptic timer instantly.
      touchFn('touchstart', e);
    }, { passive: false });
    touchInputsEl.addEventListener('touchmove', e => {
      e.preventDefault(); // Prevents accidental scrolling while dragging across the D-pad.
      touchFn('touchmove', e);
    }, { passive: false });
    touchInputsEl.addEventListener('touchend', e => touchFn('touchend', e));
    touchInputsEl.addEventListener('touchcancel', e => touchFn('touchend', e));
    touchInputsEl.addEventListener('contextmenu', e => e.preventDefault());
  }
}

function setupCopyUrl() {
  const el = document.querySelector('.button--copyurl');
  el.classList.remove('hidden');

  // TODO: this should just return the string.
  const getShareableUrl = Module.cwrap('get_shareable_url', 'undefined', []);
  el.addEventListener('click', () => {
    getShareableUrl();
    if (ZC.url) navigator.clipboard.writeText(ZC.url);
  });
}

function setupOpenTestMode() {
  const el = document.querySelector('.button--open-testmode');
  el.classList.remove('hidden');

  const openTestMode = Module.cwrap('open_test_mode', null, []);
  el.addEventListener('click', () => {
    openTestMode();
  });
}

function checkForGamepads() {
  const hasGamepad = navigator.getGamepads().some(Boolean);
  for (const el of [...document.querySelectorAll('.touch-inputs')]) {
    el.classList.toggle('hidden', hasGamepad);
  }
}

function goFullscreen() {
  document.querySelector('main').requestFullscreen();
}

// Don't run this in the workers.
if (typeof window !== 'undefined' && TARGET !== 'playground') {
  main().catch(err => {
    console.error(err);
    document.querySelector('.content').textContent = err.toString();
  });
  checkForGamepads();
  window.addEventListener('gamepadconnected', checkForGamepads);
  window.addEventListener('gamepaddisconnected', checkForGamepads);

  const fullscreenEl = document.createElement('button');
  fullscreenEl.textContent = 'Fullscreen';
  fullscreenEl.classList.add('panel-button');
  fullscreenEl.addEventListener('click', goFullscreen);
  document.addEventListener('DOMContentLoaded', () => {
    document.querySelector('.panel-buttons').append(fullscreenEl);
  });

  // If using gamepad, probably want to go fullscreen.
  // TODO https://bugs.chromium.org/p/chromium/issues/detail?id=1413066
  // if (TARGET === 'zplayer') {
  //   window.addEventListener('gamepadconnected', goFullscreen, { once: true });
  // }
}
